const DEMO_KEY = 'kme-demo-v1';
const SELECTED_KEY = 'kme-character-' + (LIVE ? CONFIG.supabaseUrl : 'demo');
const $ = id => document.getElementById(id);
const esc = value => String(value ?? '').replace(/[&<>"']/g, c => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const iconPaths = {
 chat:'<path d="M21 11a8 8 0 0 1-8 8H5l-4 3V11a10 10 0 0 1 20 0Z"/>',game:'<rect x="2" y="6" width="20" height="13" rx="4"/><path d="M6 12h6m-3-3v6m7-4h1m2 3h1"/>',leaf:'<path d="M20 3C7 2 2 9 5 15c4 8 15 1 15-12ZM4 22 16 8"/>',
 grid:'<rect x="3" y="3" width="7" height="7" rx="1"/><rect x="14" y="3" width="7" height="7" rx="1"/><rect x="3" y="14" width="7" height="7" rx="1"/><rect x="14" y="14" width="7" height="7" rx="1"/>',
 users:'<path d="M16 21v-2a4 4 0 0 0-4-4H6a4 4 0 0 0-4 4v2m20 0v-2a4 4 0 0 0-3-3.87M16 3.13a4 4 0 0 1 0 7.75"/><circle cx="9" cy="7" r="4"/>',
 activity:'<path d="M3 12h4l3-8 4 16 3-8h4"/>',alert:'<path d="m12 3 10 18H2L12 3Z"/><path d="M12 9v5m0 3v1"/>',shield:'<path d="M12 3 3 7v5c0 5 9 9 9 9s9-4 9-9V7l-9-4Z"/><path d="m8 12 3 3 5-6"/>',plus:'<path d="M12 5v14M5 12h14"/>',switch:'<path d="M4 7h15m-4-4 4 4-4 4M20 17H5m4-4-4 4 4 4"/>',muted:'<path d="m11 5-6 4H2v6h3l6 4V5Zm6 4 5 6m0-6-5 6"/>',sound:'<path d="m11 5-6 4H2v6h3l6 4V5Zm4 3a5 5 0 0 1 0 8m3-11a9 9 0 0 1 0 14"/>'
};
function icon(name){ return '<svg class="icon" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.6" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">'+(iconPaths[name]||iconPaths.grid)+'</svg>'; }
function avatarSvg(type='goblin',color='#c3f970'){
 const safeColor = /^#[\da-f]{6}$/i.test(color) ? color : '#c3f970';
 const faces = {
 goblin:'<path d="M10 22H2v16h10m44-16h6v16h-8" fill="'+safeColor+'"/><path d="M16 10h32v8h8v30h-8v8H16v-8H8V18h8z" fill="'+safeColor+'"/><path d="M16 24h12v12H16zm20 0h12v12H36z" fill="#16210e"/><path d="M19 25h5v5h-5zm20 0h5v5h-5z" fill="#f0f5df"/><path d="M24 41h16v6H24z" fill="#16210e"/><path d="M24 41h5v9h-5zm11 0h5v9h-5z" fill="#eff4d9"/>',
 rat:'<path d="M5 9h17v19H5zm37 0h17v19H42z" fill="#a9b4a0"/><path d="M9 13h9v10H9zm37 0h9v10h-9z" fill="#e6ad9b"/><path d="M16 20h32v8h8v18h-8v10H16V46H8V28h8z" fill="#c2c9b7"/><path d="M18 29h8v8h-8zm20 0h8v8h-8z" fill="#17210f"/><path d="M27 39h10v6H27z" fill="#e6ad9b"/><path d="M29 46h6v8h-6" fill="#f6f4df"/>',
 skull:'<path d="M16 9h32v7h8v29H45v12H19V45H8V16h8z" fill="#e9ebda"/><path d="M15 23h14v15H15zm20 0h14v15H35z" fill="#1b2116"/><path d="M29 38h6v7h-6zM25 49v8m8-8v8m8-8v8" stroke="#1b2116" stroke-width="3"/>',
 frog:'<path d="M8 10h18v12H8zm30 0h18v12H38z" fill="'+safeColor+'"/><path d="M8 21h48v29H8zM16 50h32v6H16z" fill="'+safeColor+'"/><path d="M12 14h10v12H12zm30 0h10v12H42z" fill="#f4f4dc"/><path d="M17 17h5v8h-5zm25 0h5v8h-5z" fill="#17210f"/><path d="M17 37v7h30v-7" fill="none" stroke="#17210f" stroke-width="4"/><path d="M10 32h10v5H10zm34 0h10v5H44z" fill="#f39d8755"/>',
 robot:'<path d="M30 3h4v12h-4z" fill="#b1bba5"/><path d="M27 2h10v7H27z" fill="'+safeColor+'"/><path d="M10 16h44v37H10zM3 26h7v16H3zm51 0h7v16h-7z" fill="#b1bba5"/><path d="M15 21h34v20H15z" fill="#27331e"/><path d="M19 25h9v9h-9zm17 0h9v9h-9z" fill="'+safeColor+'"/><path d="M22 45h20v4H22z" fill="#27331e"/>',
 alien:'<path d="M16 8h32v7h8v24h-8v10h-8v8H24v-8h-8V39H8V15h8z" fill="'+safeColor+'"/><path d="M14 22h12v6h6v12H20v-6h-6zm36 0H38v6h-6v12h12v-6h6z" fill="#17210f"/><path d="M27 47h10v3H27z" fill="#17210f"/>'
 };
 return '<svg viewBox="0 0 64 64" xmlns="http://www.w3.org/2000/svg" aria-hidden="true" shape-rendering="crispEdges">'+(faces[type]||faces.goblin)+'</svg>';
}
function avatar(profile,size=''){return '<span class="avatar '+size+'" style="--av:'+esc(profile.color)+'">'+avatarSvg(profile.avatar,profile.color)+'</span>';}
const AVATARS=['goblin','rat','skull','frog','robot','alien'];
const COLORS=['#C3F970','#F3D178','#C1A7EF','#F0A07C','#91C7E5','#D5DCCA'];
const state={profiles:[],events:[],selected:null,page:'home',filter:'all',busy:false,sound:false,editing:false,chosenAvatar:'goblin',chosenColor:COLORS[0],holdUntil:0,lastEvent:null,repo:null,refreshing:false,version:0};
let toastTimeout,holdInterval,pollInterval;
const storage={get(key){try{return localStorage.getItem(key);}catch{return null;}},set(key,value){try{localStorage.setItem(key,value);}catch{}},remove(key){try{localStorage.removeItem(key);}catch{}}};
const uid=()=>crypto.randomUUID ? crypto.randomUUID() : 'xxxxxxxx-xxxx-4xxx-yxxx-xxxxxxxxxxxx'.replace(/[xy]/g,c=>{const r=Math.floor(Math.random()*16);return(c==='x'?r:(r&3|8)).toString(16);});
function startOfDay(time=Date.now()){const d=new Date(time);d.setHours(0,0,0,0);return d.getTime();}
function weekStart(){const d=new Date();d.setHours(0,0,0,0);d.setDate(d.getDate()-((d.getDay()+6)%7));return d.getTime();}
function timeParts(ms){const seconds=Math.max(0,Math.floor(ms/1000));return {days:Math.floor(seconds/86400),hours:Math.floor(seconds/3600)%24,minutes:Math.floor(seconds/60)%60,seconds:seconds%60};}
function compact(ms){const t=timeParts(ms);return t.days ? t.days+'d '+t.hours+'h' : t.hours ? t.hours+'h '+t.minutes+'m' : t.minutes+'m';}
function lastUse(profile){return state.events.filter(e=>e.profile_id===profile.id&&e.kind==='used').reduce((max,e)=>Math.max(max,new Date(e.created_at).getTime()),0);}
function streakStart(profile){return Math.max(new Date(profile.quit_started_at).getTime(),lastUse(profile));}
function streak(profile){return Math.max(0,Date.now()-streakStart(profile));}
function rank(profile){const hours=streak(profile)/3600000;return hours>=168?'DIRECTOR OF HOLDING THE LINE':hours>=72?'RETIRED POUCH GOBLIN':hours>=24?'PROCUREMENT RESISTANCE':hours>=1?'NICOTINE LEFT ON READ':'FRESHLY CLOCKED IN';}
function relative(date){const seconds=Math.max(0,(Date.now()-new Date(date).getTime())/1000);return seconds<60?'just now':seconds<3600?Math.floor(seconds/60)+'m ago':seconds<86400?Math.floor(seconds/3600)+'h ago':Math.floor(seconds/86400)+'d ago';}
function localInput(date){const d=new Date(date);return new Date(d.getTime()-d.getTimezoneOffset()*60000).toISOString().slice(0,16);}
function seedDemo(){
 const now=Date.now(),hour=3600000,day=24*hour;
 const people=[['Goblin #1','goblin',COLORS[0],3*day],['Rat CEO','rat',COLORS[1],5*day],['Intern 404','robot',COLORS[4],day+7*hour],['Desk Goblin','skull',COLORS[2],2*day+9*hour]].map(([name,avatar,color,ago])=>({id:uid(),name,avatar,color,quit_started_at:new Date(now-ago).toISOString(),created_at:new Date(now-ago).toISOString()}));
 const events=[];
 function add(index,kind,ago,note){events.push({id:uid(),profile_id:people[index].id,kind,created_at:new Date(now-ago).toISOString(),created_by:'sample',product:kind==='used'?'Pouch':null,nicotine_mg:null,note:note||null});}
 add(0,'craving',22*60000);add(0,'resisted',19*60000);add(1,'resisted',44*60000);add(2,'craving',7*60000,'The kiosk is testing my loyalty.');add(3,'resisted',2*hour);add(1,'craving',3*hour);add(0,'used',2*day+14*hour);add(2,'resisted',4*hour);add(3,'resisted',day+2*hour);add(0,'resisted',day+3*hour);
 return {profiles:people,events};
}
class DemoRepository{
 constructor(){let data;try{data=JSON.parse(storage.get(DEMO_KEY));}catch{}if(!data||!Array.isArray(data.profiles)||!Array.isArray(data.events))data=seedDemo();this.data=data;this.userId='demo-device';this.save();}
 save(){storage.set(DEMO_KEY,JSON.stringify(this.data));}
 async load(){return structuredClone(this.data);}
 async saveProfile(values,id){const profile=id?this.data.profiles.find(p=>p.id===id):null;if(this.data.profiles.some(p=>p.name.toLocaleLowerCase()===values.name.toLocaleLowerCase()&&p.id!==id))throw new Error('That employee name is already taken.');const saved=profile?Object.assign(profile,values):{...values,id:uid(),created_at:new Date().toISOString()};if(!profile)this.data.profiles.push(saved);this.save();return structuredClone(saved);}
 async addEvent(values){const event={...values,id:uid(),created_at:new Date().toISOString(),created_by:this.userId};this.data.events.push(event);this.save();return structuredClone(event);}
 async undo(event){if(event.created_by!==this.userId||Date.now()-new Date(event.created_at).getTime()>300000)throw new Error('The five-minute undo window has ended.');this.data.events=this.data.events.filter(e=>e.id!==event.id);this.save();}
}
class LiveRepository{
 async init(){
  if(!/^https:\/\/[a-z0-9-]+\.supabase\.co\/?$/i.test(CONFIG.supabaseUrl)||!CONFIG.publishableKey.startsWith('sb_publishable_'))throw new Error('The group connection has not been configured correctly.');
  if(!window.supabase?.createClient)throw new Error('The connection library could not load. Reload and retry.');const {createClient}=window.supabase;
  this.client=createClient(CONFIG.supabaseUrl,CONFIG.publishableKey,{auth:{persistSession:true,autoRefreshToken:true,detectSessionInUrl:false}});this.pendingWrites=new Map();
  const {data,error}=await this.client.auth.getSession();if(error)throw error;this.userId=data.session?.user.id;return this;
 }
 async admitted(){if(!this.userId)return false;const {data,error}=await this.client.rpc('kme_has_access');if(error)throw error;return data===true;}
 async enter(password){
  if(!this.userId){const {data,error}=await this.client.auth.signInAnonymously();if(error){if(error.message?.toLowerCase().includes('anonymous'))throw new Error('The group administrator needs to enable anonymous device sessions in Supabase.');throw error;}this.userId=data.user.id;}
  const {data,error}=await this.client.rpc('kme_enter',{p_password:password});if(error)throw error;if(!data?.ok)throw new Error(data?.message||'Unable to enter the group.');
 }
 async load(){
  if(!(await this.admitted())){const error=new Error('The group access code has changed. Enter it again.');error.accessExpired=true;throw error;}
  const {data:profiles,error}=await this.client.from('kme_profiles').select('*').order('created_at');if(error)throw error;
  const recentPromise=this.client.from('kme_activity').select('*').order('created_at',{ascending:false}).order('id',{ascending:false}).limit(100);
  const weekPromise=(async()=>{const events=[];let page=0;while(true){const {data,error}=await this.client.from('kme_activity').select('*').gte('created_at',new Date(weekStart()).toISOString()).order('created_at',{ascending:true}).order('id',{ascending:true}).range(page*500,page*500+499);if(error)throw error;events.push(...data);if(data.length<500)break;page++;}return events;})();
  const lastPromise=Promise.all(profiles.map(async profile=>{const {data,error}=await this.client.from('kme_activity').select('*').eq('profile_id',profile.id).eq('kind','used').order('created_at',{ascending:false}).limit(1);if(error)throw error;return data;}));
  const [recent,week,last]=await Promise.all([recentPromise,weekPromise,lastPromise]);if(recent.error)throw recent.error;const events=[...new Map([...recent.data,...week,...last.flat()].map(e=>[e.id,e])).values()];return {profiles,events};
 }
 async saveProfile(values,id){const query=id?this.client.from('kme_profiles').update(values).eq('id',id):this.client.from('kme_profiles').insert({...values,id:uid()});const {data,error}=await query.select().single();if(error){if(error.code==='23505')throw new Error('That employee name is already taken.');throw error;}return data;}
 async addEvent(values){const key=JSON.stringify(values);let payload=this.pendingWrites.get(key);if(!payload){payload={...values,id:uid()};this.pendingWrites.set(key,payload);}let {data,error}=await this.client.from('kme_activity').insert(payload).select().single();if(error?.code==='23505'){const existing=await this.client.from('kme_activity').select('*').eq('id',payload.id).single();data=existing.data;error=existing.error;}if(error)throw error;this.pendingWrites.delete(key);return data;}
 async undo(event){const {data,error}=await this.client.from('kme_activity').delete().eq('id',event.id).select('id');if(error)throw error;if(!data?.length)throw new Error('The five-minute undo window has ended.');}
 async leave(){await this.client.auth.signOut();this.userId=null;}
}
function setBusy(value){state.busy=value;document.querySelectorAll('.action-button,#profile-submit,#use-submit,#hold-win,#hold-use,#enter-button,#demo-enter').forEach(b=>b.disabled=value);}
function sound(kind){if(!state.sound||kind==='used')return;try{const AudioContext=window.AudioContext||window.webkitAudioContext;if(!AudioContext)return;const ctx=new AudioContext();const tone=ctx.createOscillator(),gain=ctx.createGain();tone.type='square';tone.frequency.setValueAtTime(kind==='resisted'?550:220,ctx.currentTime);tone.frequency.setValueAtTime(kind==='resisted'?830:330,ctx.currentTime+.09);gain.gain.setValueAtTime(.035,ctx.currentTime);gain.gain.exponentialRampToValueAtTime(.001,ctx.currentTime+.23);tone.connect(gain);gain.connect(ctx.destination);tone.start();tone.stop(ctx.currentTime+.25);tone.onended=()=>ctx.close();}catch{}}
function showToast(message,event=null){clearTimeout(toastTimeout);$('toast-message').textContent=message;state.lastEvent=event;$('undo-button').hidden=!event;$('toast').hidden=false;toastTimeout=setTimeout(()=>{$('toast').hidden=true;},event?15000:6500);}
function showDialog(id){if(!$(id).open)$(id).showModal();}
function closeDialog(id){$(id).close();if(id==='hold-dialog')clearInterval(holdInterval);}
function chooseProfile(id){if(!state.profiles.some(p=>p.id===id))return;state.selected=id;storage.set(SELECTED_KEY,id);closeDialog('picker');render();navigate('home');}
function picker(){renderPicker();showDialog('picker');}
function renderPicker(){$('picker-grid').innerHTML=state.profiles.map(p=>'<button class="pick-person" data-character="'+esc(p.id)+'">'+avatar(p)+'<strong>'+esc(p.name)+'</strong></button>').join('')+'<button class="pick-person picker-create" data-action="create"><span>+</span><strong>New employee</strong></button>';}
function navigate(page){state.page=page;for(const name of ['home','squad','activity'])$('page-'+name).hidden=name!==page;document.querySelectorAll('[data-page]').forEach(b=>{const active=b.dataset.page===page;b.classList.toggle('active',active);if(active)b.setAttribute('aria-current','page');else b.removeAttribute('aria-current');});window.scrollTo({top:0,behavior:'instant'});}
function renderTimers(){const selected=state.profiles.find(p=>p.id===state.selected);if(selected){const t=timeParts(streak(selected));$('main-timer').innerHTML=[['days','DAYS'],['hours','HRS'],['minutes','MIN'],['seconds','SEC']].map(([key,label],i)=>(i?'<span class="timer-colon" aria-hidden="true">:</span>':'')+'<div class="timer-part"><strong>'+String(t[key]).padStart(2,'0')+'</strong><small>'+label+'</small></div>').join('');$('main-timer').setAttribute('aria-label',t.days+' days, '+t.hours+' hours, '+t.minutes+' minutes, '+t.seconds+' seconds since last nicotine');$('rank').textContent=rank(selected);}
 document.querySelectorAll('[data-timer-profile]').forEach(el=>{const profile=state.profiles.find(p=>p.id===el.dataset.timerProfile);if(profile)el.textContent=compact(streak(profile));});}
function eventMarkup(event){const p=state.profiles.find(p=>p.id===event.profile_id);if(!p)return '';const labels={craving:'logged a craving',resisted:'got through a craving',used:'logged nicotine use'};const notes={craving:'Employee requesting backup. Hold the line.',resisted:'Unauthorized nicotine procurement prevented.',used:'An honest check-in. The next attempt starts here.'};return '<article class="feed-row">'+avatar(p,'small')+'<div class="feed-text"><strong>'+esc(p.name)+'</strong> '+labels[event.kind]+'<span class="feed-badge '+event.kind+'">'+(event.kind==='resisted'?'WIN':event.kind.toUpperCase())+'</span><p>'+notes[event.kind]+(event.kind==='used'&&event.product?' · '+esc(event.product)+(event.nicotine_mg!==null&&event.nicotine_mg!==undefined?' · '+esc(event.nicotine_mg)+' mg product strength':''):'')+'</p>'+(event.note?'<blockquote>'+esc(event.note)+'</blockquote>':'')+'</div><time class="feed-time" datetime="'+esc(event.created_at)+'" title="'+esc(new Date(event.created_at).toLocaleString())+'">'+relative(event.created_at)+'</time></article>';}
function render(){
 if(state.selected&&!state.profiles.some(p=>p.id===state.selected)){state.selected=null;storage.remove(SELECTED_KEY);}const person=state.profiles.find(p=>p.id===state.selected);
 $('side-name').textContent=person?.name||'Choose employee';$('side-avatar').innerHTML=person?avatar(person,'small'):avatarSvg('goblin');$('greeting').textContent=person?'Good to see you, '+person.name+'. Big Nicotine is having a bad day.':'Your squad starts with one employee.';
 $('today-date').textContent=new Date().toLocaleDateString('en-GB',{weekday:'short',day:'2-digit',month:'short'}).toUpperCase();
 for(const kind of ['craving','resisted','used'])$('stat-'+kind).textContent=state.events.filter(e=>e.profile_id===state.selected&&e.kind===kind&&new Date(e.created_at).getTime()>=startOfDay()).length;
 $('squad-preview').innerHTML=state.profiles.slice(0,5).map(p=>'<div class="squad-person row">'+avatar(p)+'<div style="flex:1;min-width:0"><div class="person-name">'+esc(p.name)+(p.id===state.selected?' <span class="muted">(you)</span>':'')+'</div><div class="person-role">'+(state.events.some(e=>e.profile_id===p.id&&e.kind==='craving'&&Date.now()-new Date(e.created_at).getTime()<15*60000&&!state.events.some(r=>r.profile_id===p.id&&(r.kind==='resisted'||r.kind==='used')&&new Date(r.created_at)>new Date(e.created_at)))?'Requesting backup':'Holding the line')+'</div></div><div class="person-time"><span data-timer-profile="'+esc(p.id)+'">'+compact(streak(p))+'</span><small>current streak</small></div></div>').join('')||'<div class="empty">Your first employee goes here.</div>';
 $('squad-grid').innerHTML=state.profiles.map(p=>'<article class="card character-card '+(p.id===state.selected?'selected':'')+'">'+(p.id===state.selected?'<span class="selected-label eyebrow">THAT’S YOU</span>':'')+avatar(p,'large')+'<h2>'+esc(p.name)+'</h2><span class="tag">'+esc(rank(p))+'</span><div class="character-streak" data-timer-profile="'+esc(p.id)+'">'+compact(streak(p))+'</div><p class="small-copy">current nicotine-free streak</p><button class="button secondary wide" data-character="'+esc(p.id)+'">'+(p.id===state.selected?'Back to your desk ↗':'Clock in as '+esc(p.name)+' ↗')+'</button></article>').join('')+'<button class="add-character" data-action="create"><span class="plus">+</span><strong>Expand the department.</strong><span class="small-copy">Create a new character</span></button>';
 const recent=[...state.events].sort((a,b)=>new Date(b.created_at)-new Date(a.created_at));$('feed-preview').innerHTML=recent.slice(0,4).map(eventMarkup).join('')||'<div class="empty">No reports yet. Start with an honest check-in.</div>';
 const filtered=recent.filter(e=>state.filter==='all'||e.kind===state.filter).slice(0,100);$('activity-list').innerHTML=filtered.map(eventMarkup).join('')||'<div class="empty">No reports in this category yet.</div>';
 const buckets=new Map();state.events.filter(e=>e.kind==='resisted'&&new Date(e.created_at).getTime()>=weekStart()).forEach(e=>{const key=e.profile_id+'-'+startOfDay(e.created_at);buckets.set(key,(buckets.get(key)||0)+1);});const wins=[...buckets.values()].reduce((total,count)=>total+Math.min(count,3),0);$('raid-fill').style.width=Math.min(100,wins/30*100)+'%';$('raid-bar').setAttribute('aria-valuenow',Math.min(30,wins));$('raid-count').textContent=Math.min(30,wins)+' / 30 group wins';$('raid-label').textContent=wins>=30?'DEPARTMENT SHUT DOWN':'BOSS STILL EMPLOYED';renderTimers();renderPicker();
}
async function refresh(silent=false){if(state.refreshing)return;state.refreshing=true;const version=state.version;try{const data=await state.repo.load();if(version!==state.version)return;state.profiles=data.profiles;state.events=data.events;if(data.world!==undefined){state.world=data.world;state.worldAt=Date.now();}state.worldError=data.worldError||'';$('sync-error').hidden=true;if(LIVE)$('connection-status').innerHTML='<span class="dot"></span>GROUP CONNECTED';render();}catch(error){if(error.accessExpired){await lock(false);$('door-error').textContent=error.message;}else{$('sync-error').textContent='Couldn’t refresh the squad. Displaying the last loaded data. Check your connection and try again.';$('sync-error').hidden=false;if(LIVE)$('connection-status').innerHTML='<span class="dot" style="background:var(--yellow)"></span>RECONNECTING';if(!silent)throw error;}}finally{state.refreshing=false;}}
async function openApp(){const saved=storage.get(SELECTED_KEY);await refresh();$('entrance').hidden=true;$('app').hidden=false;if(state.profiles.some(p=>p.id===saved)){state.selected=saved;render();}else{state.selected=null;render();picker();}clearInterval(pollInterval);if(LIVE)pollInterval=setInterval(()=>{if(!document.hidden&&!state.busy)refresh(true);},15000);navigate('home');}
async function lock(signOut=true){clearInterval(pollInterval);clearInterval(holdInterval);for(const dialog of document.querySelectorAll('dialog'))if(dialog.open)dialog.close();$('app').hidden=true;$('entrance').hidden=false;$('toast').hidden=true;if(LIVE&&signOut)await state.repo.leave();state.events=[];state.profiles=[];$('door-error').textContent='';$('group-password').value='';window.scrollTo(0,0);}
function openProfile(edit=false){if(state.busy)return;closeDialog('picker');state.editing=edit;const profile=edit?state.profiles.find(p=>p.id===state.selected):null;state.chosenAvatar=profile?.avatar||'goblin';state.chosenColor=profile?.color||COLORS[0];$('profile-title').textContent=edit?'Your employee card.':'New employee.';$('profile-submit').textContent=edit?'Save employee card':'Clock me in ↗';$('profile-name').value=profile?.name||'';$('quit-date').value=localInput(profile?.quit_started_at||Date.now());$('quit-date').max=localInput(Date.now());$('profile-error').textContent='';renderAvatarChoices();showDialog('profile-dialog');}
function renderAvatarChoices(){$('avatar-options').innerHTML=AVATARS.map(type=>'<button type="button" class="avatar-option '+(state.chosenAvatar===type?'selected':'')+'" data-avatar="'+type+'" aria-label="Choose '+type+'" aria-pressed="'+(state.chosenAvatar===type)+'">'+avatarSvg(type,state.chosenColor)+'</button>').join('');$('color-options').innerHTML=COLORS.map(color=>'<button type="button" class="swatch '+(state.chosenColor.toUpperCase()===color?'selected':'')+'" style="background:'+color+'" data-color="'+color+'" aria-label="Choose '+color+'" aria-pressed="'+(state.chosenColor.toUpperCase()===color)+'"></button>').join('');}
function openUse(){if(state.busy)return;closeDialog('hold-dialog');$('use-form').reset();$('use-error').textContent='';showDialog('use-dialog');}
function startHold(){$('hold-description').textContent=LIVE?'Your craving is logged. Your squad can see the report. Take a pause. Message a friend. You decide what comes next.':'Your demo craving is logged on this device. Take a pause. You decide what comes next.';state.holdUntil=Date.now()+90000;$('hold-heading').textContent='Stay here for a minute.';clearInterval(holdInterval);function update(){const remaining=Math.max(0,Math.ceil((state.holdUntil-Date.now())/1000));$('hold-time').textContent=String(Math.floor(remaining/60)).padStart(2,'0')+':'+String(remaining%60).padStart(2,'0');if(!remaining){$('hold-heading').textContent='Still here. Still in the game.';clearInterval(holdInterval);}}update();holdInterval=setInterval(update,250);showDialog('hold-dialog');}
async function logEvent(kind,extra={}){if(state.busy)return null;if(!state.selected){picker();return null;}setBusy(true);try{const saved=await state.repo.addEvent({profile_id:state.selected,kind,...extra});state.version++;state.events=[...new Map([...state.events,saved].map(e=>[e.id,e])).values()];render();sound(kind);if(kind==='resisted'){$('main-timer').parentElement.classList.remove('celebrate');void $('main-timer').parentElement.offsetWidth;$('main-timer').parentElement.classList.add('celebrate');}const messages={craving:'Craving filed. Management has requested backup.',resisted:'Nicotine denied. Excellent insubordination.',used:'Check-in saved. Keep going.'};showToast(messages[kind],saved);return saved;}catch(error){if(kind==='used')$('use-error').textContent='Couldn’t confirm this check-in. Check your connection and retry.';else showToast('Couldn’t confirm that report. Check your connection and retry.');return null;}finally{setBusy(false);}}
document.addEventListener('click',async event=>{
 const target=event.target.closest('button');if(!target)return;
 if(target.dataset.page){navigate(target.dataset.page);return;}
 if(target.dataset.close){closeDialog(target.dataset.close);if(target.dataset.close==='profile-dialog'&&!state.profiles.length)picker();return;}
 if(target.dataset.character){if(!state.busy)chooseProfile(target.dataset.character);return;}
 if(target.dataset.avatar){state.chosenAvatar=target.dataset.avatar;renderAvatarChoices();return;}
 if(target.dataset.color){state.chosenColor=target.dataset.color;renderAvatarChoices();return;}
 if(target.dataset.filter){state.filter=target.dataset.filter;document.querySelectorAll('[data-filter]').forEach(b=>b.classList.toggle('active',b===target));render();return;}
 switch(target.dataset.action){case'pick':picker();break;case'create':openProfile(false);break;case'edit':openProfile(true);break;case'reset-demo':if(!LIVE&&!state.busy){storage.set(DEMO_KEY,JSON.stringify(seedDemo()));storage.remove(SELECTED_KEY);state.repo=new DemoRepository();state.selected=null;await refresh();navigate('home');picker();showToast('Demo reset. Sample employees restored.');}break;case'lock':if(!state.busy)try{await lock();}catch{showToast('Unable to clock out. Try again.');}break;case'craving':openQuick();break;case'resisted':await logEvent('resisted');break;case'used':openUse();break;}
});
$('profile-form').addEventListener('submit',async event=>{event.preventDefault();if(state.busy)return;const name=$('profile-name').value.trim(),quit=new Date($('quit-date').value);if(!name||name.length>24){$('profile-error').textContent='Choose a name between 1 and 24 characters.';return;}if(!Number.isFinite(quit.getTime())||quit.getTime()>Date.now()+60000){$('profile-error').textContent='Choose a starting time in the past or right now.';return;}setBusy(true);try{const values={name,avatar:state.chosenAvatar,color:state.chosenColor,quit_started_at:quit.toISOString()};const saved=await state.repo.saveProfile(values,state.editing?state.selected:null);state.version++;const index=state.profiles.findIndex(p=>p.id===saved.id);if(index>=0)state.profiles[index]=saved;else state.profiles.push(saved);state.selected=saved.id;storage.set(SELECTED_KEY,saved.id);render();closeDialog('profile-dialog');navigate('home');showToast(state.editing?'Employee card updated.':'Welcome to the department, '+saved.name+'.');}catch(error){$('profile-error').textContent=error.message?.includes('already taken')?error.message:'Couldn’t save your employee card. Check your connection and retry.';}finally{setBusy(false);}});
$('use-form').addEventListener('submit',async event=>{event.preventDefault();if(state.busy)return;const raw=$('use-mg').value;const amount=raw===''?null:Number(raw);if(amount!==null&&(!Number.isFinite(amount)||amount<0||amount>=100000)){$('use-error').textContent='Enter a valid strength, or leave it blank.';return;}const saved=await logEvent('used',{product:$('use-product').value,nicotine_mg:amount,note:$('use-note').value.trim()||null});if(saved)closeDialog('use-dialog');});
$('hold-win').addEventListener('click',async()=>{if(await logEvent('resisted'))closeDialog('hold-dialog');});$('hold-use').addEventListener('click',openUse);
$('undo-button').addEventListener('click',async()=>{const event=state.lastEvent;if(state.busy||!event)return;setBusy(true);try{await state.repo.undo(event);state.version++;state.events=state.events.filter(e=>e.id!==event.id);if(LIVE)await refresh(true);render();closeDialog('hold-dialog');showToast('Report undone.');}catch(error){showToast(error.message||'Couldn’t undo this report.');}finally{setBusy(false);}});
$('toast-dismiss').addEventListener('click',()=>{$('toast').hidden=true;});
$('sound-button').addEventListener('click',()=>{state.sound=!state.sound;storage.set('kme-sound',state.sound?'on':'off');$('sound-button').innerHTML=icon(state.sound?'sound':'muted');$('sound-button').setAttribute('aria-label',state.sound?'Mute sound':'Enable sound');$('sound-button').title=state.sound?'Sound on':'Sound off';if(state.sound)sound('resisted');});
