$('door-form').addEventListener('submit',async event=>{event.preventDefault();if(!LIVE||state.busy)return;const password=$('group-password').value;if(!password){$('door-error').textContent='Enter the shared group access code.';return;}setBusy(true);$('door-error').textContent='';try{if(!state.repo)state.repo=await new LiveRepository().init();await state.repo.enter(password);$('group-password').value='';await openApp();}catch(error){$('door-error').textContent=error.message?.includes('fetch')?'Couldn’t reach the group. Check your connection and retry.':error.message||'Unable to enter the facility.';}finally{setBusy(false);}});
