 const W=480,H=680,MAX=300,NAMES=['COMMON','UNCOMMON','RARE','EPIC','LEGENDARY','MYTHIC','ASTRAL','ETHEREAL','VOID','AETHER'],COLORS=['#A8B099','#83BE93','#81C8E8','#B5A0ED','#F3D178','#F296B8','#72E2D2','#D8D2FC','#B692FF','#F4FFD6'];let mounted=null;
