  if(e.elapsed>=e.bossAt){e.objects.push({kind:'boss',x:W/2,y:H+80,vx:0,vy:-32,r:47,hp:4,age:0,warn:.8,phase:0,gone:false,shoot:1.6});e.bossAt+=60;message(e,'MANAGER INSPECTION','#d0b8f2');}
