DemoRepository.prototype.extractionStart=async function(id,mode){await this.world();const v=this.data.v3,c=v.campaign;if(mode==='finale'&&c.status!=='finale')throw new Error('The boss finale is not open yet.');const last=v.runs.at(-1);if(last&&Date.now()-last.started<22000)throw new Error('Wait a moment between escapes.');v.runs.forEach(r=>{if(!r.result)r.cancelled=true;});const r={id:uid(),profile_id:id,nonce:uid(),seed:Math.floor(Math.random()*2147483647),started:Date.now(),seen:Date.now(),active:0,mode,campaign_id:c.id};v.runs.push(r);this.save();return {id:r.id,nonce:r.nonce,seed:r.seed,assist:this.data.events.some(e=>e.profile_id===id&&e.kind==='used'&&Date.parse(e.created_at)>=Date.parse(c.started_at))?.85:1};};
DemoRepository.prototype.extractionPulse=async function(id,nonce){const v=this.data.v3,r=v.runs.find(r=>r.id===id);if(!r||r.cancelled)throw new Error('This run ended.');if(nonce===r.previous)return r.reply;if(nonce!==r.nonce)throw new Error('Stale checkpoint.');const delta=Math.min(30,300-r.active,Math.max(0,Math.floor((Date.now()-r.seen)/1000)));r.active+=delta;r.seen=Date.now();const c=v.campaign;if(r.mode==='finale'&&c.id===r.campaign_id&&c.status==='finale'){c.finale_seconds+=delta;const m=c.members.find(m=>m.profile_id===r.profile_id);if(m)m.finale_seconds+=delta;if(c.finale_seconds>=c.finale_goal){v.campaign=demoCampaign(this,c.level+1);v.campaign.previous={level:c.level};}}r.previous=r.nonce;r.nonce=uid();r.reply={ok:true,nonce:r.nonce,active_seconds:r.active,finale_seconds:c.finale_seconds,finale_goal:c.finale_goal};this.save();return r.reply;};
DemoRepository.prototype.extractionFinish=async function(id,score,greed,capsules,extract=true){const v=this.data.v3,r=v.runs.find(r=>r.id===id);if(!r)throw new Error('Unknown run.');if(r.result)return r.result;if(!extract){r.cancelled=true;this.save();return {ok:true,cancelled:true,loot:[],damage:0};}if(r.cancelled||Date.now()-r.started<20000)throw new Error('Complete twenty seconds before extracting.');await this.extractionPulse(id,r.nonce);const key=r.profile_id+'-'+utcDay(),d=v.daily[key]??={successes:0,chips:0},c=v.campaign;let damage=0;if(c.id===r.campaign_id&&['wearing','sealed'].includes(c.status)&&c.members.some(m=>m.profile_id===r.profile_id)){damage=d.successes<2?Math.min(60,Math.max(1,Math.floor(score/20*2**Math.min(greed,4)))):d.chips<20?1:0;if(d.successes>=2&&damage)d.chips++;c.damage+=damage;}d.successes++;const s=v.stats[r.profile_id]??={best:0,extracts:0,damage:0,capsules:0,inventory:{},equipped:null};s.best=Math.max(s.best,score);s.extracts++;s.damage+=damage;const min=Math.min(3,Math.floor(greed/2)),total=RARITY_WEIGHTS.slice(min).reduce((a,b)=>a+b,0),loot=[];for(let i=0;i<Math.min(12,capsules);i++){let roll=Math.floor(Math.random()*total),tier=min;while(tier<9&&roll>=RARITY_WEIGHTS[tier])roll-=RARITY_WEIGHTS[tier++];s.inventory[tier]=(s.inventory[tier]||0)+1;s.capsules++;loot.push({tier});}r.result={ok:true,score,damage,loot};this.save();return r.result;};
