if(LIVE&&window.KME_CONFIG?.turnstileSiteKey){const script=document.createElement('script');script.src='https://challenges.cloudflare.com/turnstile/v0/api.js?render=explicit';script.async=true;script.onload=()=>{captchaWidget=window.turnstile.render('#captcha-slot',{sitekey:window.KME_CONFIG.turnstileSiteKey,theme:'dark',size:'flexible',callback:token=>{captchaToken=token;},'expired-callback':()=>{captchaToken='';},'error-callback':()=>{$('door-error').textContent='The bot check could not load. Reload and try again.';}});};script.onerror=()=>{$('door-error').textContent='The bot check could not load. Reload and try again.';};document.head.append(script);}
const originalEnter=LiveRepository.prototype.enter;LiveRepository.prototype.enter=async function(password){if(!this.userId&&window.KME_CONFIG?.turnstileSiteKey){if(!captchaToken)throw new Error('Complete the bot check first.');const token=captchaToken;captchaToken='';try{const {data,error}=await this.client.auth.signInAnonymously({options:{captchaToken:token}});if(error)throw error;this.userId=data.user.id;}finally{if(captchaWidget!==null)window.turnstile?.reset(captchaWidget);}}return originalEnter.call(this,password);};
