function coach(){
  if(tutorial===0&&Math.hypot(s.player.x,s.player.z-10)>4)tutorial++;
  if(tutorial===1&&s.shots>2)tutorial++;
  if(tutorial===2&&(s.stats.dodges||s.stats.parries||s.player.gadgetCD>0))tutorial++;
  if(tutorial===3&&(Object.keys(s.weapons).length>1||s.turrets.length))tutorial++;
  if(tutorial===4&&s.caches.some(c=>c.open))tutorial++;
  let el=$('.bs-coach');if(!el){el=document.createElement('div');el.className='bs-coach';$('.bs-hud').append(el);}
  const hints=['MOVE / WASD or left stick. Explore the shelter courtyard.','AIM + FIRE / Mouse and click, or right stick.','DEFEND / Space to dash, R to parry, Q for your class gadget.','BONGO / E near the shelter counter. Buy a weapon or turret.','SCAVENGE / Enter a building and open a locker with E.','SIGNALS / A, B and C appear on your map. Link them, finish looting, then call the guardian and extract.'];
  el.textContent=practice?'SAFE PRACTICE / Inspect build to test any of the 15 weapons. No rewards.':s.time<150?hints[Math.min(5,tutorial)]:'';el.hidden=!el.textContent;
}
function settings(){if(active){paused=true;clearInput();}show('<span class="bs-tag">FIELD OPTIONS</span><h3>Make yourself<br>comfortable. Briefly.</h3><div class="bs-options"><label>MASTER VOLUME<input data-bs-volume type="range" min="0" max="1" step=".05" value="'+options.volume+'"></label><label>CAMERA SHAKE<input data-bs-shake type="range" min="0" max=".5" step=".05" value="'+options.shake+'"></label><label>GRAPHICS<select data-bs-quality><option value="auto" '+(options.quality==='auto'?'selected':'')+'>Auto / desktop shadows</option><option value="low" '+(options.quality==='low'?'selected':'')+'>Performance / fewer effects</option></select></label><label><input data-bs-haptics type="checkbox" '+(options.haptics?'checked':'')+'> Touch vibration on damage</label><label><input data-bs-assist type="checkbox" '+(options.assist?'checked':'')+'> Touch aim assist · respects walls</label><label><input data-bs-handed type="checkbox" '+(options.leftHanded?'checked':'')+'> Left-handed touch layout</label></div>'+(active?'<button class="bs-loadout-link">Inspect build / test armory</button>':'')+'<button class="button '+(active?'bs-resume':'bs-options-back')+'">'+(active?'Resume':'Back to deployment')+'</button>');}
