 const action=mod?'Buy & install':weapon?'Buy & equip':'Buy upgrade',scope=mod?'For '+E.WEAPONS[s.weapon].name:weapon?'Attachments stay on your previous weapon':it.key==='magnet'?'Applies to your operative':'Applies to your shelter';
