function controls(){const node=$('.urge-keyboard'),ids=e?.targets.map(t=>t.id+':'+t.hp).join(',')||'';if(node.dataset.ids===ids)return;const focused=document.activeElement?.dataset.target;node.dataset.ids=ids;node.innerHTML=(e?.targets||[]).filter(t=>!t.gone).map((t,i)=>'<button data-target="'+t.id+'" '+(t.kind==='friend'?'class="friendly"':'')+'>'+({friend:'Mushroom',armour:'Armour ×'+t.hp,smoke:'Ghost',beetle:'Beetle',bat:'Bat'})[t.kind]+' '+(i+1)+'</button>').join('');if(focused)node.querySelector('[data-target="'+focused+'"]')?.focus({preventScroll:true});}
function frame(now){if(!alive||!active)return;if(document.hidden){bank(false);return;}tick(e,Math.min(.25,(now-last)/1000));last=now;draw(ctx,e);clock();$('.urge-clock').textContent=Math.floor(e.elapsed)+'s · '+e.score+' points';$('.urge-progress').textContent=e.hits+' hits · '+e.strikes+'/5 mistakes';controls();if(e.status==='done'){bank(false);return;}raf=requestAnimationFrame(frame);}
