on(canvas,'pointerdown',ev=>{if(!active)return;ev.preventDefault();const r=canvas.getBoundingClientRect();tap(e,(ev.clientX-r.left)/r.width*W,(ev.clientY-r.top)/r.height*H);receipt();draw(ctx,e);});on(container,'click',ev=>{const b=ev.target.closest('button');if(!b)return;if(b.dataset.target&&active){const t=e.targets.find(t=>t.id===Number(b.dataset.target));if(t){tap(e,t.x,t.y);receipt();draw(ctx,e);controls();}}if(b.dataset.urgeMin)o.setMinutes?.(Number(b.dataset.urgeMin));});on($('.urge-start'),'click',start);on($('.urge-bank'),'click',()=>bank(canResist()));on($('.urge-bank-only'),'click',()=>bank(false));on(document,'visibilitychange',()=>{if(document.hidden&&active)bank(false);});const interval=setInterval(clock,250);clock();draw(ctx,null);root.KMEArt.ready.then(()=>{if(alive)draw(ctx,e);});
