/* Two independent cabinets: BLACKSITE is permanent; only the side cabinet rotates. */
state.arcadeSlot='main';
const v6DemoWorld=DemoRepository.prototype.world;DemoRepository.prototype.world=async function(){const w=await v6DemoWorld.call(this);if(this.data.v4.current.game_key==='blacksite')Object.assign(this.data.v4.current,{game_key:'smoke-break',game_name:'Smoke Break: Extraction',build:'4.0.0'});this.data.v6??={scores:{},legacyScores:structuredClone(w.arcade.scores||[])};this.data.v6.legacyScores??=[];const grouped=new Map();for(const r of this.data.v3.runs){if(!r.game_key||!r.result||r.result.score===undefined)continue;const k=r.profile_id+':'+r.game_key,v=grouped.get(k)||{profile_id:r.profile_id,game_key:r.game_key,best:0,extracts:0};v.best=Math.max(v.best,r.result.score);v.extracts++;grouped.set(k,v);}w.arcade.scores=[...this.data.v6.legacyScores,...grouped.values()];w.version=6;w.main_game={game_key:'blacksite',game_name:'BLACKSITE: Shelter Shift',build:'6.0.0'};w.main_scores=Object.values(this.data.v6.scores);return w;};
LiveRepository.prototype.blacksiteFinish=function(id,score,wave,capsules,outcome){return liveRpc(this,'kme_blacksite_finish',{p_run_id:id,p_score:score,p_wave:wave,p_capsules:capsules,p_outcome:outcome});};
const v6DemoStart=DemoRepository.prototype.arcadeStart;DemoRepository.prototype.arcadeStart=async function(id,mode,key){const t=key==='blacksite'?await this.extractionStart(id,mode):await v6DemoStart.call(this,id,mode,key),r=this.data.v3.runs.find(r=>r.id===t.id);if(r)r.game_key=key;this.save();return{...t,game_key:key,max_seconds:key==='blacksite'&&mode!=='finale'?null:300};};
DemoRepository.prototype.blacksiteFinish=async function(id,score,wave,capsules,outcome){const r=this.data.v3.runs.find(r=>r.id===id);if(!r)throw Error('Unknown raid receipt.');if(r.result)return r.result;if(!['extracted','defeated','retreated'].includes(outcome))throw Error('Unknown raid outcome.');const success=outcome==='extracted',result=await this.extractionFinish(id,success?score:Math.floor(score*.2),success?Math.min(14,Math.max(0,wave-1)):0,success?capsules:Math.floor(capsules*.2),true);const stats=this.data.v6.scores[r.profile_id]??={profile_id:r.profile_id,best_score:0,best_wave:0,longest_seconds:0,extractions:0,deaths:0};stats.best_score=Math.max(stats.best_score,result.score);stats.best_wave=Math.max(stats.best_wave,wave);stats.longest_seconds=Math.max(stats.longest_seconds,Math.floor((Date.now()-r.started)/1000));stats.extractions+=success?1:0;stats.deaths+=success?0:1;r.result={...result,blacksite:{outcome,wave,retained_percent:success?100:20}};this.save();return r.result;};
arcadeKey=function(){return state.arcadeSlot==='main'?'blacksite':state.world?.arcade?.current?.game_key||'smoke-break';};
mountArena=function(){if($('urge-dialog')?.open)return;if(!me()||!v3Ready()){arcadeHost.destroy();$('arena-game').innerHTML=empty('Choose your character to enter.');return;}const gameKey=arcadeKey(),mode=state.extractionMode,key=state.selected+':'+mode+':'+gameKey;if(arenaProfile===key)return;arcadeHost.destroy();const game=window.KMEGames.registry[gameKey];if(!game){$('arena-game').innerHTML='<div class="v4-update-required"><h2>A new rotating game landed.</h2><p>Refresh to load it. BLACKSITE remains available in its own tab.</p><button class="button" data-v4="reload">Refresh</button></div>';arenaProfile=null;return;}const p=me(),repo=state.repo;arcadeHost.game=game;game.mount($('arena-game'),{profile:p,mode,gameKey,deviceId:repo.userId||'demo',canRecover:()=>state.profiles.some(x=>x.id===p.id),onStart:()=>repo.arcadeStart(p.id,mode,gameKey),onPulse:(id,nonce)=>repo.extractionPulse(id,nonce),onFinish:async(id,score,greed,caps,extract,details)=>{const r=gameKey==='blacksite'&&details?await repo.blacksiteFinish(id,score,details.wave,caps,details.outcome):await repo.extractionFinish(id,score,greed,caps,extract);state.version++;await refreshWorld();return r;},onCancel:id=>repo.extractionFinish(id,0,0,0,false)});arenaProfile=key;};
const v6Scores=renderV3Scores;renderV3Scores=function(){if(state.arcadeSlot!=='main')return v6Scores();const list=[...(state.world?.main_scores||[])].sort((a,b)=>b.best_wave-a.best_wave||b.longest_seconds-a.longest_seconds);$('arena-scores').innerHTML=list.length?'<table class="scoreboard"><thead><tr><th>GOBLIN</th><th>WAVE</th><th>LONGEST</th></tr></thead><tbody>'+list.map(s=>'<tr><td>'+esc(state.profiles.find(p=>p.id===s.profile_id)?.name||'Former employee')+'</td><td>'+s.best_wave+'</td><td>'+Math.floor(s.longest_seconds/60)+'m '+s.longest_seconds%60+'s</td></tr>').join('')+'</tbody></table>':empty('Permanent BLACKSITE records: highest wave and longest shift. Earlier loot and scores are retained.');};
const v6Render=renderV4;renderV4=function(){v6Render();if(!$('v6-game-tabs'))return;for(const b of document.querySelectorAll('[data-v6-slot]')){const selected=b.dataset.v6Slot===state.arcadeSlot;b.classList.toggle('selected',selected);b.setAttribute('aria-pressed',String(selected));}$('v4-live-title').textContent=state.arcadeSlot==='main'?'BLACKSITE: Shelter Shift':state.world?.arcade?.current?.game_name||'Rotating Arcade';$('v3-summary').textContent='KME v6 · PERMANENT BLACKSITE + ROTATING ARCADE';const label=$('v6-rotation-name');if(label)label.textContent=state.world?.arcade?.current?.game_name||'Short-session games';};
document.addEventListener('click',e=>{const b=e.target.closest('[data-v6-slot]');if(!b)return;const target=b.dataset.v6Slot;if(!['main','rotating'].includes(target)||target===state.arcadeSlot)return;arcadeHost.destroy();arenaProfile=null;state.arcadeSlot=target;state.extractionMode='arcade';mountArena();renderV4();renderV3Scores();});
for(const Repo of[LiveRepository,DemoRepository]){const before=Repo.prototype.deleteProfile;Repo.prototype.deleteProfile=async function(id,name){const r=await before.call(this,id,name);try{for(const key of Object.keys(localStorage))if(key.startsWith('kme-blacksite-result-')&&key.includes('-'+id+'-'))localStorage.removeItem(key);}catch{}if(this.data?.v6){delete this.data.v6.scores[id];this.data.v6.legacyScores=this.data.v6.legacyScores?.filter(s=>s.profile_id!==id)||[];this.save();}return r;};}

const v6DemoExport=DemoRepository.prototype.exportProfile;DemoRepository.prototype.exportProfile=async function(id){return{...await v6DemoExport.call(this,id),blacksite_stats:this.data.v6?.scores[id]||null};};

const CURRENT_PATCH=window.KME_PATCHES.current;
LiveRepository.prototype.reliefFinish=function(id,hits,score,resisted){return liveRpc(this,'kme_relief_finish',{p_run_id:id,p_hits:hits,p_score:score,p_resisted:resisted});};
DemoRepository.prototype.reliefFinish=async function(id,hits,score,resisted){const r=this.data.v4.runs.find(r=>r.id===id);if(!r)throw Error('Unknown quick-game receipt.');if(r.result?.score===undefined){const seconds=Math.max(0,(Date.now()-r.started)/1000),result=await this.reliefBank(id,Math.min(60,hits,Math.floor(Math.min(90,seconds)/.7)));r.result={...result,score,resisted_logged:false};this.data.v6.reliefScores??=[];this.data.v6.reliefScores.push({run_id:id,profile_id:r.profile_id,score,hits,seconds:Math.floor(seconds)});}if(resisted&&!r.result.resisted_logged&&this.data.v3?.privacy?.allow_nicotine&&this.data.profiles.find(p=>p.id===r.profile_id)?.tracking_enabled!==false){const event=await this.addEvent({profile_id:r.profile_id,kind:'resisted'});r.result.resisted_logged=true;r.result.resisted_event_id=event.id;}this.save();return r.result;};
const quickDemoWorld=DemoRepository.prototype.world;DemoRepository.prototype.world=async function(){const w=await quickDemoWorld.call(this),groups=new Map();for(const row of this.data.v6.reliefScores||[]){const g=groups.get(row.profile_id)||{profile_id:row.profile_id,best:0,runs:0};g.best=Math.max(g.best,row.score);g.runs++;groups.set(row.profile_id,g);}w.relief_scores=[...groups.values()];w.arcade_history=this.data.v6.arcadeHistory||[];w.patch=CURRENT_PATCH;return w;};
holdUpdate=function(){const value=readHold();if(!value){$('hold-live-pill').hidden=true;return;}const sec=Math.max(0,Math.ceil((value.until-Date.now())/1000)),label=String(Math.floor(sec/60)).padStart(2,'0')+':'+String(sec%60).padStart(2,'0');state.holdUntil=value.until;$('hold-live-pill').textContent=sec?'I’m tweaking · '+label:'Timer done · open Tweakmax ↗';$('hold-time').textContent=label;renderHoldPill();};
openQuick=function(){if(!me()){picker();return;}if($('urge-dialog').open)return;if(!v4Ready()){showToast('The group connection is not ready.');return;}const player=me(),repo=state.repo,key=reliefReceiptKey(),owner=repo.userId||'demo';let receipt=null;try{const r=JSON.parse(storage.get(key)||'null');if(r?.owner===owner)receipt=r;}catch{}if(!readHold())setHoldMinutes(3);else restoreHold();const timerKey=holdKey();arcadeHost.destroy();arenaProfile=null;showDialog('urge-dialog');$('urge-character').textContent=player.name;urgeInstance=KMEUrge.mount($('urge-mount'),{receipt,onStart:()=>{if(!readHold())setHoldMinutes(3);return repo.reliefStart(player.id);},onReceipt:r=>{if(r)storage.set(key,JSON.stringify({...r,owner}));else storage.remove(key);},canResist:()=>!!me()&&state.selected===player.id&&healthAllowed()&&clockOn(me()),timerRemaining:()=>{try{return Math.max(0,(JSON.parse(storage.get(timerKey)||'null')?.until||0)-Date.now());}catch{return 0;}},setMinutes:n=>{if(state.selected===player.id&&[3,5].includes(n))setHoldMinutes(n);},onBank:async(id,hits,score,resisted)=>{const r=await repo.reliefFinish(id,hits,score,resisted);state.version++;if(r.resisted_logged){if(state.selected===player.id)clearHold();else storage.remove(timerKey);await refresh(true);}else await refreshWorld();return r;}});$('urge-log').disabled=!healthAllowed()||!clockOn(player);$('urge-log').textContent='Optional: log a craving for the crew';};
startHold=function(){openQuick();};
$('urge-dialog').addEventListener('close',()=>{if(!$('urge-dialog').open&&state.page==='arena')mountArena();});
function gameCatalogue(){const map=new Map([['blacksite',{key:'blacksite',name:'BLACKSITE: Shelter Shift',kind:'PERMANENT MAIN',note:'Endless shelter survival. Highest wave, longest shift and banked score.'}],['urge-breaker',{key:'urge-breaker',name:'Tweakmax / Urge Breaker',kind:'QUICK GAME',note:'Rapid difficulty escalation. Coping timer and bankable competitive score.'}],['smoke-break',{key:'smoke-break',name:'Smoke Break: Extraction',kind:'ROTATING / ARCHIVE',note:'The illustrated extraction cabinet. Earlier records stay here.'}],['legacy-breakroom',{key:'legacy-breakroom',name:'Original Break-room Arcade',kind:'ARCHIVED BUILD',note:'The original pre-Extraction minigame. Its recorded scores remain available.'}]]);for(const row of state.world?.arcade_history||[])if(!map.has(row.game_key))map.set(row.game_key,{key:row.game_key,name:row.game_name||row.game_key,kind:'ROTATING HISTORY',note:'A previously published rotating game.'});const c=state.world?.arcade?.current;if(c&&!map.has(c.game_key))map.set(c.game_key,{key:c.game_key,name:c.game_name,kind:'CURRENT ROTATION',note:'The current short-session side game.'});for(const s of state.world?.arcade?.scores||[])if(!map.has(s.game_key))map.set(s.game_key,{key:s.game_key,name:s.game_key.replaceAll('-',' '),kind:'ARCHIVED RECORDS',note:'A previous game with retained scores.'});return[...map.values()];}
