$('v6-library').innerHTML='<span class="v3-kicker">EVERY GAME HAS ITS OWN RECORDS</span><h2>The game library.</h2><div class="v6-library-grid">'+entries.map(g=>'<article class="'+(g.key===selected.key?'selected':'')+'"><small>'+esc(g.key===current?'CURRENT ROTATION':g.kind)+'</small><h3>'+esc(g.name)+'</h3><p>'+esc(g.note)+'</p><button class="section-link" data-library-score="'+esc(g.key)+'">Leaderboard & history ↗</button>'+((g.key==='blacksite'||g.key==='urge-breaker'||g.key===current)?'<button class="section-link" data-library-play="'+esc(g.key)+'">Play ↗</button>':'')+'</article>').join('')+'</div><div id="v6-library-board"></div>';
let rows=[];if(selected.key==='blacksite')rows=(state.world?.main_scores||[]).map(s=>({profile_id:s.profile_id,score:s.best_score,detail:'Wave '+s.best_wave+' · '+Math.floor(s.longest_seconds/60)+'m longest · '+s.extractions+' extracts'}));else if(selected.key==='urge-breaker')rows=(state.world?.relief_scores||[]).map(s=>({...s,score:s.best,detail:s.runs+' banked runs'}));else if(selected.key==='legacy-breakroom'){const m=new Map();for(const s of state.world?.scores||[])if(!m.has(s.profile_id)||s.score>m.get(s.profile_id).score)m.set(s.profile_id,s);for(const p of state.world?.profiles||[])if(p.arena_best>0&&!m.has(p.id))m.set(p.id,{profile_id:p.id,score:p.arena_best});rows=[...m.values()];}else rows=(state.world?.arcade?.scores||[]).filter(s=>s.game_key===selected.key).map(s=>({...s,score:s.best,detail:s.extracts+' banked extracts'}));rows.sort((a,b)=>b.score-a.score);
const milestones={blacksite:['Initial BLACKSITE extraction build','v2.0 Shelter Shift: permanent main game','v2.1: fair shield impacts, illustrated shop and named bosses'],"urge-breaker":['Classic Urge Breaker: bankable fragments','v2.0 Tweakmax: fast escalation, coping clock and scores','v2.1: selectable drawing side quests share the coping timer'],"smoke-break":['Original Smoke Break extraction game','Illustrated Extraction overhaul','Independent rotating cabinet'],"legacy-breakroom":['Original pre-Extraction arcade','Archived build; historical scores retained']};
const legacy=selected.key==='blacksite'?(state.world?.arcade?.scores||[]).filter(s=>s.game_key==='blacksite'):[],history=(state.world?.arcade_history||[]).filter(h=>h.game_key===selected.key);
$('v6-library-board').innerHTML='<h3>'+esc(selected.name)+' · leaderboard</h3>'+(rows.length?'<table class="scoreboard"><thead><tr><th>GOBLIN</th><th>SCORE</th><th>RECORD</th></tr></thead><tbody>'+rows.map(r=>'<tr><td>'+esc(state.profiles.find(p=>p.id===r.profile_id)?.name||'Former employee')+'</td><td>'+r.score+'</td><td>'+esc(r.detail||'Historical score')+'</td></tr>').join('')+'</tbody></table>':empty('No competitive scores banked for this game yet.'))+(legacy.length?'<p class="v3-note">Earlier BLACKSITE banked-haul records are preserved: '+legacy.map(r=>esc(state.profiles.find(p=>p.id===r.profile_id)?.name||'Former employee')+' '+r.best).join(' · ')+'</p>':'')+'<ul class="v6-game-timeline">'+(milestones[selected.key]||['Published rotating game']).map(m=>'<li>'+esc(m)+'</li>').join('')+'</ul><p class="v3-note">'+(history.length?history.map(h=>esc(h.build||'Published build')+' · '+esc(h.published_at?new Date(h.published_at).toLocaleDateString():'Published')).join(' / '):selected.key==='urge-breaker'?'Classic Urge Breaker recorded fragments. Competitive points start with v2.0.':selected.key==='blacksite'?'Earlier Extraction-era BLACKSITE is retained in its haul records. Shelter Shift starts its wave/time records here.':'This game predates the rotating ballot archive.')+'</p>';
