const quickExport=DemoRepository.prototype.exportProfile;DemoRepository.prototype.exportProfile=async function(id){return{...await quickExport.call(this,id),tweakmax_scores:this.data.v6?.reliefScores?.filter(s=>s.profile_id===id)||[]};};
