/* Crew Chat: paged text metadata; drawings are fetched only on an explicit tap. */
LiveRepository.prototype.chatList=function(cursor=null,thread=null,revision=null){return liveRpc(this,'kme_chat_list',{p_before:cursor?.created_at||null,p_before_id:cursor?.id||null,p_thread:thread,p_known_revision:revision});};
LiveRepository.prototype.chatImage=function(id){return liveRpc(this,'kme_chat_image',{p_post_id:id});};
LiveRepository.prototype.chatDrawing=function(profile,id,prompt,png,resisted){return liveRpc(this,'kme_chat_drawing',{p_profile_id:profile,p_submission_id:id,p_prompt:prompt,p_png_base64:png.split(',')[1],p_resisted:resisted});};
const CHAT_RULES={version:1,message_limit:10000,drawing_limit:100,drawing_days:7,drawing_bytes:24576};
function chatDemoCleanup(repo){const v=repo.data.v2;v.drawings??=[];v.drawingReceipts??=[];const removed=new Set(v.posts.filter(p=>p.deleted_at).map(p=>p.id));v.posts=v.posts.filter(p=>!removed.has(p.id)&&!removed.has(p.parent_id));while(v.posts.length>10000){const parents=new Set(v.posts.map(p=>p.parent_id)),leaves=v.posts.filter(p=>!parents.has(p.id)).sort((a,b)=>Date.parse(a.created_at)-Date.parse(b.created_at)||a.id.localeCompare(b.id));const ids=new Set(leaves.slice(0,v.posts.length-10000).map(p=>p.id));v.posts=v.posts.filter(p=>!ids.has(p.id));}const ids=new Set(v.posts.map(p=>p.id));v.drawings=v.drawings.filter(d=>ids.has(d.post_id)&&Date.parse(d.created_at)>Date.now()-7*86400000).sort((a,b)=>Date.parse(b.created_at)-Date.parse(a.created_at)||b.post_id.localeCompare(a.post_id)).slice(0,100);v.drawingReceipts=v.drawingReceipts.filter(d=>ids.has(d.post_id));v.votes=v.votes.filter(x=>ids.has(x.post_id)).slice(-20000);}
const chatDemoWorld=DemoRepository.prototype.world;DemoRepository.prototype.world=async function(){const w=await chatDemoWorld.call(this);chatDemoCleanup(this);delete w.posts;w.chat=CHAT_RULES;return w;};
DemoRepository.prototype.chatList=async function(cursor=null,thread=null,revision=null){demoWorld(this);chatDemoCleanup(this);const v=this.data.v2,rev=v.chatRevision||1;if(!cursor&&!thread&&revision===rev)return{ok:true,unchanged:true,revision:rev};if(thread&&!v.posts.some(p=>p.id===thread))return{ok:true,items:[],more:false,revision:rev,gone:true};const all=v.posts.filter(p=>thread?p.parent_id===thread:!p.parent_id).filter(p=>!cursor||p.created_at<cursor.created_at||p.created_at===cursor.created_at&&p.id<cursor.id).sort((a,b)=>b.created_at.localeCompare(a.created_at)||b.id.localeCompare(a.id));return{ok:true,revision:rev,more:all.length>30,items:all.slice(0,30).map(p=>({...p,can_delete:p.created_by===this.userId,own_device:p.created_by===this.userId,votes:v.votes.filter(q=>q.post_id===p.id).length,voted_by_me:v.votes.some(q=>q.post_id===p.id&&q.user_id===this.userId),comment_count:v.posts.filter(q=>q.parent_id===p.id).length,drawing:v.drawings.some(d=>d.post_id===p.id),drawing_expired:v.drawingReceipts.some(d=>d.post_id===p.id)&&!v.drawings.some(d=>d.post_id===p.id)}))};};
DemoRepository.prototype.chatImage=async function(id){chatDemoCleanup(this);const d=this.data.v2.drawings.find(d=>d.post_id===id);return d?{ok:true,data_url:d.png,expires_at:new Date(Date.parse(d.created_at)+7*86400000).toISOString()}:{ok:false,expired:true,message:'This drawing has expired or was removed.'};};
DemoRepository.prototype.social=async function(action,profile,target=null,body=null){demoWorld(this);const v=this.data.v2;if(!this.data.profiles.some(p=>p.id===profile))throw Error('Choose a character.');let id=null;if(['post','comment'].includes(action)){body=String(body||'').trim();if(!body||[...body].length>280)throw Error('Write 1–280 characters.');if(action==='comment'&&!v.posts.some(p=>p.id===target&&!p.parent_id))throw Error('That conversation is gone.');id=uid();v.posts.unshift({id,profile_id:profile,parent_id:action==='comment'?target:null,body,created_at:new Date().toISOString(),created_by:this.userId});}else{const p=v.posts.find(p=>p.id===target);if(!p)throw Error('That message is gone.');if(action==='delete'){if(p.profile_id!==profile||p.created_by!==this.userId)throw Error('Only the posting device and character can remove this message.');p.deleted_at=new Date().toISOString();}else if(action==='vote'){if(p.profile_id===profile||p.created_by===this.userId)throw Error('React to someone else’s message.');const old=v.votes.find(q=>q.post_id===target&&q.user_id===this.userId);if(old)v.votes=v.votes.filter(q=>q!==old);else if(!v.votes.some(q=>q.post_id===target&&q.profile_id===profile))v.votes.push({post_id:target,profile_id:profile,user_id:this.userId});}else throw Error('Unknown chat action.');}v.chatRevision=(v.chatRevision||1)+1;chatDemoCleanup(this);this.save();return{ok:true,id};};
DemoRepository.prototype.chatDrawing=async function(profile,id,prompt,png,resisted){demoWorld(this);if(!this.data.profiles.some(p=>p.id===profile))throw Error('Choose a character.');const v=this.data.v2;chatDemoCleanup(this);const old=v.posts.find(p=>p.id===id);if(old){if(old.profile_id!==profile||old.created_by!==this.userId||!v.drawingReceipts.some(r=>r.post_id===id))throw Error('That drawing belongs to another device.');return{ok:true,id,resisted_logged:!!v.drawingReceipts.find(r=>r.post_id===id)?.resisted_logged,duplicate:true};}if(!/^data:image\/png;base64,[a-zA-Z0-9+/=]+$/.test(png)||png.split(',')[1].length>32768)throw Error('Drawing is too large.');const now=new Date().toISOString();let event=null;if(resisted&&this.data.v3?.privacy?.allow_nicotine&&this.data.profiles.find(p=>p.id===profile)?.tracking_enabled!==false)event=await this.addEvent({profile_id:profile,kind:'resisted'});v.posts.unshift({id,profile_id:profile,parent_id:null,body:'Drawing challenge: '+prompt,created_at:now,created_by:this.userId});v.drawings.push({post_id:id,prompt,png,created_at:now});v.drawingReceipts.push({post_id:id,resisted_logged:!!event});v.chatRevision=(v.chatRevision||1)+1;chatDemoCleanup(this);this.save();return{ok:true,id,resisted_logged:!!event};};

let chatGeneration=0,chatRows=[],chatReplies=[],chatMore=false,replyMore=false,chatRevision=null,chatAt=0,chatLoading=false,threadLoading=false,loadedThread=null,threadRequest=null,threadAt=0,chatOwner=null,chatError='',chatBlockedUntil=0;const chatPictures=new Map();
function chatReset(){chatGeneration++;chatLoading=false;threadLoading=false;chatRows=[];chatReplies=[];chatMore=replyMore=false;chatRevision=null;chatAt=0;chatError='';chatBlockedUntil=0;loadedThread=null;threadRequest=null;threadAt=0;chatPictures.clear();}
function chatReady(){return state.world?.chat?.version===1;}
function chatResult(r){if(r?.ok===false){if(r.budget_paused)chatBlockedUntil=Date.now()+15*60000;throw Error(r.message||'Could not load chat.');}return r;}
function chatMerge(old,items){const m=new Map(old.map(p=>[p.id,p]));for(const p of items)m.set(p.id,p);return[...m.values()].sort((a,b)=>b.created_at.localeCompare(a.created_at)||b.id.localeCompare(a.id)).slice(0,1000);}
async function chatLoad(older=false,force=false){if(chatLoading||!chatReady()||!state.repo||chatBlockedUntil>Date.now())return;const repo=state.repo,generation=chatGeneration;chatLoading=true;chatAt=Date.now();try{const r=chatResult(await repo.chatList(older?chatRows.at(-1):null,null,older||force?null:chatRevision));if(repo!==state.repo||generation!==chatGeneration)return;if(!r.unchanged){chatRows=older?chatMerge(chatRows,r.items):r.items;chatMore=r.more;chatRevision=r.revision;if($('thread-dialog').open)await chatLoadThread(false,true);}chatError='';}catch(e){if(generation===chatGeneration)chatError=e.message;}finally{if(generation===chatGeneration){chatLoading=false;renderSocial();}}}
async function chatLoadThread(older=false,force=false){if(threadLoading||!state.thread||!chatReady())return;if(!force&&!older&&(loadedThread===state.thread||threadRequest===state.thread&&Date.now()-threadAt<20000))return;threadRequest=state.thread;threadAt=Date.now();const repo=state.repo,id=state.thread,generation=chatGeneration;threadLoading=true;try{const r=chatResult(await repo.chatList(older?chatReplies.at(-1):null,id));if(state.thread!==id||repo!==state.repo||generation!==chatGeneration)return;loadedThread=id;chatReplies=older?chatMerge(chatReplies,r.items):r.items;replyMore=r.more;if(r.gone){chatRows=chatRows.filter(p=>p.id!==id);chatReplies=[];}chatError='';}catch(e){if(generation===chatGeneration)chatError=e.message;}finally{if(generation===chatGeneration){threadLoading=false;renderSocial();}}}
function chatPictureMarkup(p){const cached=chatPictures.get(p.id);if(cached&&Date.parse(cached.expires_at)>Date.now())return'<figure class="chat-drawing"><img src="'+cached.data_url+'" width="320" height="240" alt="'+esc(p.body)+'"><figcaption>Drawing challenge · expires after seven days</figcaption></figure>';if(p.drawing)return'<div data-chat-imagebox="'+esc(p.id)+'"><button class="chat-image-load" data-chat-image="'+esc(p.id)+'">✎ View drawing · under 24 KiB</button></div>';return p.drawing_expired?'<p class="chat-expired">Drawing expired to save space. The conversation stays.</p>':'';}
postMarkup=function(p,thread=false){const author=state.profiles.find(x=>x.id===p.profile_id),own=p.profile_id===state.selected;return'<article class="card lounge-post"><div class="post-head">'+(author?avatar(author,'small'):'')+'<div class="post-author"><strong>'+esc(author?.name||'Former crew member')+'</strong><small>'+relative(p.created_at)+'</small></div>'+(p.can_delete&&own?'<button class="section-link" data-v2="delete-post" data-post="'+esc(p.id)+'">Remove</button>':'')+'</div><p class="post-body">'+esc(p.body)+'</p>'+chatPictureMarkup(p)+'<div class="post-actions"><button data-v2="vote" data-post="'+esc(p.id)+'" aria-pressed="'+!!p.voted_by_me+'" '+(own||p.own_device||state.v2Busy?'disabled':'')+'>▲ '+(p.votes||0)+' respect</button>'+(!thread?'<button data-v2="thread" data-post="'+esc(p.id)+'">'+(p.comment_count||0)+' replies ↗</button>':'')+'</div></article>';};
renderSocial=function(){const owner=state.repo;if(chatOwner!==owner){chatOwner=owner;chatReset();}const ready=chatReady();$('message-limit').textContent=ready?'No daily message limit. 280 characters per message. A short anti-spam cooldown keeps things usable.':'Crew Chat is waiting for its database update.';$('message-submit').disabled=!ready||state.v2Busy||!me();$('lounge-feed').innerHTML=(chatError?'<p role="status" class="chat-error">'+esc(chatError)+'</p>':'')+(chatRows.length?chatRows.map(p=>postMarkup(p)).join(''):empty(ready?(chatLoading?'Loading Crew Chat…':'No messages yet. Start a conversation.'):'Chat update is pending.'))+'<div class="chat-paging"><button data-chat-refresh '+(!ready||chatLoading?'disabled':'')+'>Refresh chat ↻</button>'+(chatMore?'<button data-chat-older '+(chatLoading?'disabled':'')+'>Older messages ↓</button>':'')+'</div>';if(state.page==='lounge'&&ready&&!document.hidden&&Date.now()-chatAt>20000)chatLoad();if(state.thread&&$('thread-dialog').open){const root=chatRows.find(p=>p.id===state.thread);$('thread-original').innerHTML=root?postMarkup(root,true):empty('This message was removed or left the retained history.');$('thread-comments').innerHTML=chatReplies.filter(p=>p.parent_id===state.thread).slice().reverse().map(p=>postMarkup(p,true)).join('')+(replyMore?'<button data-chat-replies>Older replies ↑</button>':'');$('comment-submit').disabled=!root||state.v2Busy||!ready;chatLoadThread();}};
for(const proto of[LiveRepository.prototype,DemoRepository.prototype]){const social=proto.social;proto.social=async function(...args){const result=await social.apply(this,args);chatAt=0;chatRevision=null;await chatLoad(false,true);if(state.thread)await chatLoadThread(false,true);return result;};}
document.addEventListener('click',async ev=>{const b=ev.target.closest('button');if(!b)return;if(b.hasAttribute('data-chat-refresh'))await chatLoad(false,true);if(b.hasAttribute('data-chat-older'))await chatLoad(true);if(b.hasAttribute('data-chat-replies'))await chatLoadThread(true);if(b.dataset.chatImage){b.disabled=true;const repo=state.repo,generation=chatGeneration;try{const r=chatResult(await repo.chatImage(b.dataset.chatImage));if(repo!==state.repo||generation!==chatGeneration)return;if(!/^data:image\/(png|jpeg);base64,[A-Za-z0-9+/=]+$/.test(r.data_url||'')||r.data_url.length>150000)throw Error('Invalid drawing preview.');chatPictures.set(b.dataset.chatImage,r);while(chatPictures.size>20)chatPictures.delete(chatPictures.keys().next().value);renderSocial();}catch(e){b.textContent=e.message;b.disabled=false;}}});
const chatLock=lock;lock=async function(...args){chatReset();return chatLock(...args);};
setInterval(()=>{if(state.page==='lounge'&&!document.hidden&&state.repo&&chatReady()&&!$('app').hidden)chatLoad();},20000);

const chatDemoExport=DemoRepository.prototype.exportProfile;DemoRepository.prototype.exportProfile=async function(id){chatDemoCleanup(this);const result=await chatDemoExport.call(this,id),ids=new Set(this.data.v2.posts.filter(p=>p.profile_id===id).map(p=>p.id));return {...result,drawings:this.data.v2.drawings.filter(d=>ids.has(d.post_id)).map(d=>({post_id:d.post_id,prompt:d.prompt,created_at:d.created_at,data_url:d.png}))};};

