function homeEventMarkup(ev){const p=state.profiles.find(p=>p.id===ev.profile_id),copy={resisted:'Got through a craving.',used:'An honest check-in. Keep going.',craving:'Called for a little backup.'}[ev.kind]||'Checked in.';return '<article class="community-event timeline-checkin"><span class="event-symbol '+esc(ev.kind)+'" aria-hidden="true">'+(ev.kind==='resisted'?'↗':ev.kind==='used'?'↻':'✳')+'</span><div><span class="timeline-kind">NICOTINE CHECK-IN</span><strong>'+esc(p?.name||'Crew member')+'</strong><p>'+copy+'</p><small>'+relative(ev.created_at)+'</small></div></article>';}
