 for(const el of $('squad-preview').querySelectorAll('[data-crew-timer]')){const p=profiles.get(el.dataset.crewTimer);if(!p)continue;el.textContent=crewQuitTime(p);el.setAttribute('aria-label',clockOn(p)?'Current nicotine-free streak: '+el.textContent:'Games-only character; nicotine clock disabled');}
